mapper.select:
select FROM_UNIXTIME(o.online_time) online,o.id,m.user_name userName,m.vip,m.nick_name nickName,m.login_ip loginIp from
${dbMain}.member_online o left join ${dbMain}.member_info m on m.id = o.id
where o.online_time >= #{onlineTime}
     and (m.user_name = #{searchValue} or o.id = #{searchValue})
     and m.nick_name = #{nickName}
order by o.online_time desc
